package com.yuegang.zhihui.product.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.product.api.*;import java.sql.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public final class ProductAdministrationService{private final JdbcTemplate jdbc;private final ProductService products;private final ObjectMapper json;public ProductAdministrationService(DataSource d,ProductService p,ObjectMapper j){jdbc=new JdbcTemplate(d);products=p;json=j;}@Transactional public ProductView update(String sku,UpdateProductRequest c){long id=id(sku);var before=jdbc.query("SELECT s.price,s.spu_id FROM product_sku s WHERE s.id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new Object[]{r.getBigDecimal(1),r.getLong(2)};},id);int n=jdbc.update("UPDATE product_sku s JOIN product_spu p ON p.id=s.spu_id SET p.category_id=?,p.brand_id=?,p.name=?,p.description=?,s.price=?,s.currency=?,s.traceability_code=?,s.version=s.version+1,p.version=p.version+1 WHERE s.id=? AND s.version=?",id(c.categoryId()),blank(c.brandId()),c.name(),c.description(),c.price(),c.currency(),c.traceabilityCode(),id,c.version());if(n<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("DELETE FROM product_image WHERE sku_id=?",id);int sort=0;for(String url:c.images())jdbc.update("INSERT INTO product_image(id,spu_id,sku_id,url,sort_order) VALUES(?,?,?,?,?)",next(),before[1],id,url,sort++);if(((java.math.BigDecimal)before[0]).compareTo(c.price())!=0)jdbc.update("INSERT INTO product_price_history(id,sku_id,old_price,new_price,currency) VALUES(?,?,?,?,?)",next(),id,before[0],c.price(),c.currency());event(id,"PRODUCT_UPDATED",Map.of("skuId",sku,"price",c.price(),"currency",c.currency()));return products.get(sku,false);}@Transactional public ProductBatchView batch(String sku,SaveProductBatchRequest c){long skuId=id(sku);if(c.producedOn()!=null&&c.expiresOn()!=null&&c.expiresOn().isBefore(c.producedOn()))throw new BusinessException(ErrorCode.VALIDATION_ERROR);long id=next();jdbc.update("INSERT INTO product_batch(id,sku_id,batch_no,origin,proof_url,produced_on,expires_on,trace_description) VALUES(?,?,?,?,?,?,?,?)",id,skuId,c.batchNo(),c.origin(),c.proofUrl(),c.producedOn(),c.expiresOn(),c.traceDescription());event(skuId,"PRODUCT_BATCH_CREATED",Map.of("skuId",sku,"batchId",Long.toString(id),"batchNo",c.batchNo()));return new ProductBatchView(Long.toString(id),sku,c.batchNo(),c.origin(),c.proofUrl(),c.producedOn(),c.expiresOn(),c.traceDescription());}public List<ProductBatchView>batches(String sku){long id=id(sku);return jdbc.query("SELECT id,sku_id,batch_no,origin,proof_url,produced_on,expires_on,trace_description FROM product_batch WHERE sku_id=? ORDER BY created_at DESC",(r,n)->new ProductBatchView(Long.toString(r.getLong(1)),Long.toString(r.getLong(2)),r.getString(3),r.getString(4),r.getString(5),date(r.getDate(6)),date(r.getDate(7)),r.getString(8)),id);}private void event(long sku,String type,Object payload){String event=UUID.randomUUID().toString();jdbc.update("INSERT INTO product_outbox(id,aggregate_id,event_type,payload_json) VALUES(?,?,?,?)",event,Long.toString(sku),type,write(payload));}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static LocalDate date(java.sql.Date d){return d==null?null:d.toLocalDate();}private static Long blank(String x){return x==null||x.isBlank()?null:id(x);}private static long id(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
